use kernel::prelude::*;

module! {
    type: RustMinimal,
    name: "rust_minimal",
    authors: ["Rust for Linux Contributors"],
    description: "Rust minimal sample",
    license: "GPL",
}

struct RustMinimal {
    numbers: KVec<i32>,
}

impl kernel::Module for RustMinimal {
    fn init(_module: &'static ThisModule) -> Result<Self> {
        pr_info!("Rust minimal sample (init)\n");
        let mut numbers = KVec::new();
        numbers.push(72, GFP_KERNEL)?;
        numbers.push(108, GFP_KERNEL)?;
        numbers.push(200, GFP_KERNEL)?;
        Ok(RustMinimal { numbers })
    }
}

impl Drop for RustMinimal {
    fn drop(&mut self) {
        pr_info!("My numbers are {:?}\n", self.numbers);
        pr_info!("Rust minimal sample (exit)\n");
    }
}

// Generated by module! for a loadable module (trimmed).
static mut __MOD: MaybeUninit<RustMinimal> = MaybeUninit::uninit();

#[no_mangle]
#[link_section = ".init.text"]
pub unsafe extern "C" fn init_module() -> c_int {
    // SAFETY: called exactly once by the C side via its unique name.
    unsafe { __init() }
}

#[no_mangle]
#[link_section = ".exit.text"]
pub extern "C" fn cleanup_module() {
    // SAFETY: called once, and only after init_module returned 0.
    unsafe { __exit() }
}

unsafe fn __init() -> c_int {
    let initer = <RustMinimal as InPlaceModule>::init(this_module());
    match unsafe { pin_init::raw_try_init(__MOD.as_mut_ptr(), initer) } {
        Ok(_) => 0,
        Err(e) => e.to_errno(),
    }
}

unsafe fn __exit() {
    // Invokes drop() on __MOD: this is where RustMinimal::drop runs.
    unsafe { __MOD.assume_init_drop() };
}

