/// Number of 4096-byte pages needed to hold `bytes` bytes.
///
/// ```
/// assert_eq!(pages::pages_for(0), 0);
/// assert_eq!(pages::pages_for(4096), 1);
/// assert_eq!(pages::pages_for(4097), 2);
/// ```
pub fn pages_for(bytes: usize) -> usize {
    bytes.div_ceil(4096)
}

const MAX_ERRNO: i32 = 4095;

fn try_from_errno(errno: i32) -> Option<Error> {
    if errno < -MAX_ERRNO || errno >= 0 {
        return None;
    }
    Some(Error(NonZeroI32::new(errno).unwrap()))
}

fn from_errno(errno: i32) -> Error {
    match try_from_errno(errno) {
        Some(e) => e,
        None => {
            pr_warn!("out of range errno: {}\n", errno);
            EINVAL
        }
    }
}

pub fn to_result(err: i32) -> Result {
    if err < 0 {
        Err(from_errno(err))
    } else {
        Ok(())
    }
}

