// rust/kernel/task.rs
unsafe impl AlwaysRefCounted for Task {
    fn inc_ref(&self) {
        // SAFETY: a shared reference means the refcount is nonzero.
        unsafe { bindings::get_task_struct(self.as_ptr()) };
    }
    unsafe fn dec_ref(obj: NonNull<Self>) {
        // SAFETY: the caller owns an increment.
        unsafe { bindings::put_task_struct(obj.cast().as_ptr()) }
    }
}

// rust/kernel/device.rs: same shape over get_device/put_device
unsafe impl AlwaysRefCounted for Device { /* ... */ }

// rust/kernel/sync/aref.rs
impl<T: AlwaysRefCounted> From<&T> for ARef<T> {
    fn from(b: &T) -> Self {
        b.inc_ref();
        // SAFETY: we just incremented the refcount above.
        unsafe { Self::from_raw(NonNull::from(b)) }
    }
}
impl<T: AlwaysRefCounted> Drop for ARef<T> {
    fn drop(&mut self) {
        // SAFETY: the ARef owns the reference we decrement.
        unsafe { T::dec_ref(self.ptr) };
    }
}

use kernel::{task::Task, sync::aref::ARef};

struct State {
    creator: ARef<Task>,
    index: u32,
}

impl State {
    fn new() -> Self {
        Self {
            creator: ARef::from(&**current!()),
            index: 0,
        }
    }
}

fn later(s: &State) -> Pid {
    s.creator.pid()
}

fn finish(s: State) {
    drop(s); // ARef::drop calls dec_ref
}

fn add_two(v: &Revocable<Example>) -> Option<u32> {
    let guard = rcu::read_lock();
    let e = v.try_access_with_guard(&guard)?;
    Some(e.a + e.b)
}   // guard dropped here: rcu_read_unlock()

fn leak(v: &Revocable<Example>) -> u32 {
    let guard = rcu::read_lock();
    let e = v.try_access_with_guard(&guard).unwrap();
    drop(guard);            // leave the read-side critical section
    e.a                     // ...then use the reference
}

