// error[E0505]: cannot move out of `guard` because it is borrowed
//   |     let e = v.try_access_with_guard(&guard).unwrap();
//   |                                     ------ borrow of `guard` occurs here
//   |     drop(guard);
//   |          ^^^^^ move out of `guard` occurs here
