use kernel::sync::Arc;
use kernel::workqueue::{self, impl_has_work, new_work, Work, WorkItem};

#[pin_data]
struct MyStruct {
    value: i32,
    #[pin]
    work: Work<MyStruct>,
}

impl_has_work! {
    impl HasWork<Self> for MyStruct { self.work }
}

impl MyStruct {
    fn new(value: i32) -> Result<Arc<Self>> {
        Arc::pin_init(pin_init!(MyStruct {
            value,
            work <- new_work!("MyStruct::work"),
        }), GFP_KERNEL)
    }
}

impl WorkItem for MyStruct {
    type Pointer = Arc<MyStruct>;

    fn run(this: Arc<MyStruct>) {
        pr_info!("The value is: {}\n", this.value);
    }   // the queue's reference is dropped here
}

fn print_later(val: Arc<MyStruct>) {
    let _ = workqueue::system_dfl().enqueue(val);
}

#[pin_data]
struct Job {
    buf: KVec<u8>,
    #[pin]
    result: Mutex<Option<u32>>,
    #[pin]
    done: CondVar,
    #[pin]
    work: Work<Job>,
}
// impl_has_work! as in the doc example above

impl WorkItem for Job {
    type Pointer = Arc<Job>;
    fn run(this: Arc<Job>) {
        let sum = this.buf.iter().map(|&b| u32::from(b)).sum();
        *this.result.lock() = Some(sum);
        this.done.notify_all();
    }
}

fn submit_and_wait(job: Arc<Job>) -> Result<u32> {
    workqueue::system_dfl().enqueue(job.clone()).map_err(|_| EBUSY)?;
    let mut g = job.result.lock();
    while g.is_none() {
        if job.done.wait_interruptible(&mut g) {
            return Err(EINTR);           // a signal is pending
        }
    }
    Ok(g.unwrap_or(0))
}

const VTABLE: bindings::file_operations = bindings::file_operations {
    open: Some(Self::open),
    release: Some(Self::release),
    read_iter: if T::HAS_READ_ITER { Some(Self::read_iter) } else { None },
    unlocked_ioctl: if T::HAS_IOCTL { Some(Self::ioctl) } else { None },
    // ...more optional entries...
    owner: this_module::<T::OwnerModule>().as_ptr(),
    ..pin_init::zeroed()
};

unsafe extern "C" fn open(inode: *mut bindings::inode, raw_file: *mut bindings::file) -> c_int {
    // ...generic_file_open, recover &MiscDeviceRegistration<T> from private_data...
    let ptr = match T::open(file, misc) {
        Ok(ptr) => ptr,
        Err(err) => return err.to_errno(),
    };
    // SAFETY: The open call of a file can access the private data.
    unsafe { (*raw_file).private_data = ptr.into_foreign() };
    0
}

pub unsafe trait ForeignOwnable: Sized {
    type Borrowed<'a>;
    type BorrowedMut<'a>;

    /// Rust-owned to foreign-owned: a non-null void pointer.
    fn into_foreign(self) -> *mut c_void;

    /// # Safety
    /// `ptr` must come from a previous call to `into_foreign`,
    /// and must not be passed to `from_foreign` more than once.
    unsafe fn from_foreign(ptr: *mut c_void) -> Self;

    /// # Safety
    /// `ptr` must come from `into_foreign`, and if it is ever
    /// passed to `from_foreign`, that call must happen after
    /// the lifetime 'a ends.
    unsafe fn borrow<'a>(ptr: *mut c_void) -> Self::Borrowed<'a>;

    // ...plus FOREIGN_ALIGN, try_from_foreign and borrow_mut
}

fn ioctl(me: Pin<&RustMiscDeviceFile>, _file: &File, cmd: u32, arg: usize) -> Result<isize> {
    let arg = UserPtr::from_addr(arg);
    let size = _IOC_SIZE(cmd);
    match cmd {
        RUST_MISC_DEV_GET_VALUE => me.get_value(UserSlice::new(arg, size).writer())?,
        RUST_MISC_DEV_SET_VALUE => me.set_value(UserSlice::new(arg, size).reader())?,
        RUST_MISC_DEV_HELLO => me.hello()?,
        _ => return Err(ENOTTY),
    };
    Ok(0)
}

/* Illustrative C double fetch (not from the kernel tree). */
struct req { u32 len; u8 data[64]; };

long set_req(struct req __user *u)
{
    struct req r;
    u32 len;

    if (get_user(len, &u->len))           /* fetch 1 */
        return -EFAULT;
    if (len > sizeof(r.data))             /* check  */
        return -EINVAL;
    if (copy_from_user(&r, u, sizeof(r))) /* fetch 2: len read again */
        return -EFAULT;
    memcpy(dev_buf, r.data, r.len);       /* use: r.len may now be 4096 */
    return 0;
}

fn set_req(&self, mut r: UserSliceReader) -> Result {
    let len = r.read::<u32>()? as usize;  // one fetch, into a kernel value
    let mut data = [0u8; 64];
    let dst = data.get_mut(..len).ok_or(EINVAL)?;  // check that copy
    r.read_slice(dst)?;                   // the next bytes, not len again
    // ...use len and dst only; the user's len is never read again...
    Ok(())
}

impl pci::Driver for SampleDriver {
    type IdInfo = TestIndex;
    type Data<'bound> = SampleDriverData<'bound>;
    const ID_TABLE: pci::IdTable<Self::IdInfo> = &PCI_TABLE;

    fn probe<'bound>(
        pdev: &'bound pci::Device<Core<'_>>,
        info: Option<&'bound Self::IdInfo>,
    ) -> impl PinInit<Self::Data<'bound>, Error> + 'bound {
        let info = info.ok_or(ENODEV)?;
        pdev.enable_device_mem()?;
        pdev.set_master();
        let bar = pdev.iomap_region_sized::<{ regs::END }>(0, c"rust_driver_pci")?;
        // ...run the test device once, log config space...
        Ok(SampleDriverData { pdev, bar, index: *info })
    }

    fn unbind<'bound>(_pdev: &'bound pci::Device<Core<'_>>, this: Pin<&Self::Data<'bound>>) {
        this.bar.write_reg(regs::TEST::zeroed().with_index(this.index));
    }
}

impl Drop for SampleDriverData<'_> {
    fn drop(&mut self) {
        dev_dbg!(self.pdev, "Remove Rust PCI driver sample.\n");
    }   // then `bar` drops: pci_iounmap + pci_release_region
}

kernel::module_pci_driver! { type: SampleDriver, name: "rust_driver_pci", /* ... */ }
